from pathlib import Path
import json,base64,shutil,os
ROOT=Path(__file__).resolve().parent.parent
CHARS=[
 {'id':'jiuweihu','name':'九尾狐','reading':'jiǔ wěi hú','role':'账房先生','anchor':'九条珊瑚色长尾 · 额间朱纹 · 玉坠流苏','note':'保留原画的九尾、耳缘与颈饰，用流畅曲线组织尾扇。算盘姿态呼应游戏中的账房身份。','poses':['安静相迎','眨眼招手','抱起算盘']},
 {'id':'shengsheng','name':'狌狌','reading':'xīng xīng','role':'前台接待','anchor':'蓬松白耳 · 桃心脸颊 · 弯曲长尾','note':'把原画的大白耳与暖棕毛色留作第一识别点，用手臂、视线与腰身表现迎客动作。','poses':['站好迎客','挥手招呼','躬身行礼']},
 {'id':'qiuyu','name':'犰狳','reading':'qiú yú','role':'跑堂送餐','anchor':'长兔耳 · 金色鸟喙 · 青绿鳞甲与蛇尾','note':'保留鸟喙与鳞甲，避免简化成普通兔子。从犯困到送茶、快跑，耳朵与四肢同步改变。','poses':['困困待命','端茶送客','快步跑堂']},
 {'id':'taotie','name':'饕餮','reading':'tāo tiè','role':'吞金神兽','anchor':'卷曲羊角 · 朱金纹样 · 抱碗的圆身形','note':'沿用原画的弯角、身纹与食碗，把贪吃感画成亲切的表情。献碗与鼓腮是为宣传演出设计的动作。','poses':['抱碗满足','请你尝尝','鼓腮偷吃']},
]
for ch in CHARS:
 files=sorted((ROOT/'svg').glob(ch['id']+'-*.svg'))
 if len(files)!=3: raise SystemExit(f"Need three SVG poses for {ch['id']}, found {len(files)}")
 ch['files']=[str(p.relative_to(ROOT)) for p in files]
 ch['svgs']=[p.read_text(encoding='utf-8').split('?>')[-1].strip() for p in files]
 ref=ROOT/'reference/game/public/images/yaoguai'/f"{ch['id']}.png"
 ch['reference']='data:image/png;base64,'+base64.b64encode(ref.read_bytes()).decode()
 ch['source_url']=f"https://github.com/Moshenluo/Yaoguai-Kezhan/blob/79908426b6586f6fd9a86da571e02884c6f837d4/game/public/images/yaoguai/{ch['id']}.png"
# Keep all UI lettering deterministic while maintaining offline portability.
all_text=''.join(str(v) for ch in CHARS for k,v in ch.items() if k in ['name','reading','role','anchor','note','poses'])+'妖怪客栈山海伙伴角色试绘原画参考矢量重绘四位伙伴十二种姿态原画识别点保留可编辑选择伙伴动作表情播放动作暂停动作彩色线稿纸色墨绿朱红下载当前原画与角色对照查看所有姿态跟随设备减少动态设置此处为宣传用重绘和动作设计游戏内职能以角色资料为准全部素材可离线使用表情与姿态立体的性格清楚的轮廓招呼一声客人就来参考取自仓库角色原画角色画风与动作研究SVG分组无位图嵌入'+''.join(chr(i) for i in range(32,127))
# The bundled subset keeps the existing preview reproducible with Python alone.
# Set FONT_SOURCE to a full Noto Serif CJK font when adding new UI characters.
fontpath=ROOT/'output/preview-font.otf'
fontpath.parent.mkdir(parents=True,exist_ok=True)
fontsource=os.environ.get('FONT_SOURCE')
if fontsource:
 from fontTools import subset
 options=subset.Options(font_number=int(os.environ.get('FONT_INDEX','2')))
 font=subset.load_font(fontsource,options)
 font.flavor=None
 sub=subset.Subsetter(options=options);sub.populate(text=all_text);sub.subset(font)
 font.save(fontpath)
else:
 shutil.copyfile(ROOT/'assets/preview-font.otf',fontpath)
fonturi='data:font/otf;base64,'+base64.b64encode(fontpath.read_bytes()).decode()
DATA=json.dumps(CHARS,ensure_ascii=False).replace('</','<\\/')
CSS='''
@font-face{font-family:StudySong;src:url(FONTURI)}:root{--paper:#f3ead8;--ink:#24382f;--red:#c64c35;--gold:#b58a49;--rule:#cdbd9f}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:#ede3cf;font-family:StudySong,"Noto Serif CJK SC",serif}button,a{touch-action:manipulation}button{font:inherit;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #c64c35;outline-offset:5px}.wrap{max-width:1250px;margin:auto;padding:42px 32px 50px}.top{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--rule);padding-bottom:23px}.brand{font-size:26px;font-weight:600;letter-spacing:5px}.stamp{background:var(--red);color:#fff3d8;padding:7px 11px;font-size:12px;letter-spacing:3px;transform:rotate(-3deg)}.kicker{font:11px Arial,sans-serif;letter-spacing:3px;color:#7a7664}.hero{display:flex;justify-content:space-between;align-items:end;margin:30px 0 26px;gap:30px}h1{font-size:48px;font-weight:500;letter-spacing:5px;line-height:1.18;margin:10px 0 15px}.intro{font-size:14px;line-height:1.9;max-width:410px;color:#74725f;margin:0}.tabs{display:flex;gap:9px;flex-wrap:wrap}.tab{border:1px solid var(--rule);border-radius:0;background:transparent;color:var(--ink);padding:12px 23px;letter-spacing:2px}.tab.active{background:var(--ink);color:var(--paper);border-color:var(--ink)}.workspace{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(270px,1fr);border:1px solid var(--rule);background:#f7efdf}.stage{position:relative;min-height:570px;overflow:hidden;display:flex;justify-content:center;align-items:center;background:#f3ead8;transition:background .3s}.stage:before,.stage:after{content:'';position:absolute;inset:20px;border:1px solid #b99d623d;pointer-events:none}.stage:after{inset:25px;border-color:#b99d6215}.stage #drawing{width:92%;max-width:585px;z-index:1;aspect-ratio:1}.stage svg{display:block;width:100%;height:100%;overflow:visible}.stage-label{position:absolute;top:38px;left:38px;color:#9b855f;font:10px Arial,sans-serif;letter-spacing:2px}.stage-note{position:absolute;bottom:30px;left:35px;right:35px;display:flex;justify-content:space-between;font-size:11px;color:#97876a;z-index:2}.details{padding:38px 32px;border-left:1px solid var(--rule);display:flex;flex-direction:column}.reading{font:13px Georgia,serif;font-style:italic;letter-spacing:2px;color:#948267}.name{font-size:43px;letter-spacing:8px;margin:10px 0 12px}.job{font-size:12px;letter-spacing:2px;color:var(--red);margin:0 0 22px}.anchor{font-size:13px;line-height:1.8;color:#6e735e;padding-bottom:20px;border-bottom:1px solid var(--rule)}.label{font-size:11px;letter-spacing:2px;color:#938469;margin:23px 0 12px}.poses{display:flex;gap:7px;flex-wrap:wrap}.pose{padding:10px 12px;border:1px solid var(--rule);background:transparent;font-size:12px;color:var(--ink)}.pose.active{background:#e2d2b4;border-color:#baa079}.tools{display:flex;align-items:center;gap:15px;flex-wrap:wrap;margin-top:18px}.tool{background:transparent;border:0;border-bottom:1px solid #b49c76;padding:6px 0;font-size:12px;color:#52614d}.swatches{display:flex;gap:8px;margin-left:auto}.swatch{border:2px solid transparent;width:23px;height:23px;border-radius:50%;box-shadow:0 0 0 1px #c5b89a}.swatch.active{box-shadow:0 0 0 2px #b98c44}.ref-row{display:flex;gap:16px;align-items:center;margin-top:27px;padding:18px 0;border-top:1px solid var(--rule)}.ref-box{background:#ebe1cb;border:1px solid #dbc9a6;width:104px;height:104px;flex:0 0 104px;display:flex;align-items:center;justify-content:center}.ref-box img{width:98px;height:98px;object-fit:contain}.ref-text{font-size:11px;line-height:1.9;color:#837960}.ref-text b{font-weight:500;color:var(--ink);letter-spacing:2px}.download{background:var(--red);border:0;color:var(--paper);padding:13px 18px;margin-top:auto;width:100%;font-size:13px;letter-spacing:2px}.gallery-top{display:flex;justify-content:space-between;align-items:baseline;margin:42px 0 18px}.gallery-top h2{font-size:22px;font-weight:500;letter-spacing:3px;margin:0}.gallery-top p{font-size:11px;color:#8c8169}.gallery{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#f6eddb;border:1px solid #d7c8ad;padding:14px 10px 15px;text-align:left;color:var(--ink);transition:transform .16s,border-color .16s}.card:hover{transform:translateY(-4px);border-color:#b88753}.card svg{width:100%;height:auto;display:block;aspect-ratio:1}.card .cap{display:flex;justify-content:space-between;align-items:baseline;margin:10px 5px 0;font-size:12px}.card small{font-size:10px;color:#918064}.footer{border-top:1px solid var(--rule);margin-top:30px;padding-top:20px;display:flex;justify-content:space-between;gap:20px;font-size:10px;line-height:1.9;color:#908168}.footer a{color:inherit}.line-mode svg :is(path,circle,ellipse,rect,polygon,line,polyline){fill:none!important;stroke:#735f43!important;stroke-width:1.8!important}.line-mode .ground{opacity:0}.motion .motion-head{transform-box:fill-box;transform-origin:50% 85%;animation:nod 3.9s ease-in-out infinite}.motion .motion-tail{transform-box:fill-box;transform-origin:60% 85%;animation:sway 4.5s ease-in-out infinite}.motion .motion-ear{transform-box:fill-box;transform-origin:50% 95%;animation:ear 5.3s ease-in-out infinite}@keyframes nod{0%,100%{transform:rotate(-.7deg)}50%{transform:rotate(1deg)}}@keyframes sway{0%,100%{transform:rotate(-1.3deg)}50%{transform:rotate(1.5deg)}}@keyframes ear{0%,80%,100%{transform:rotate(0)}90%{transform:rotate(1.7deg)}}@media(prefers-reduced-motion:reduce){.motion *{animation:none!important}}@media(max-width:850px){.wrap{padding:22px 18px}.hero{display:block}h1{font-size:36px}.intro{margin-top:12px}.workspace{grid-template-columns:1fr}.stage{min-height:0;aspect-ratio:1.08}.details{border-left:0;border-top:1px solid var(--rule);padding:25px}.name{font-size:34px}.ref-row{margin-top:22px}.gallery{grid-template-columns:repeat(3,1fr)}.tab{padding:10px 15px}.footer{display:block}.top .kicker{display:none}}@media(max-width:480px){.gallery{grid-template-columns:repeat(2,1fr)}.brand{font-size:21px}.stage-label{left:30px;top:30px}.stage-note{font-size:9px;left:28px;right:28px}.hero{margin-top:23px}.gallery-top p{display:none}.cap{gap:3px;flex-wrap:wrap}.tools{gap:12px}}
'''.replace('FONTURI',fonturi)
HTML=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>妖怪客栈 · SVG角色试绘</title><style>STYLE</style><body><main class="wrap"><header class="top"><div class="brand">妖怪客栈</div><div class="kicker">CHARACTER STUDY / 01</div><div class="stamp">山海伙伴</div></header><section class="hero"><div><div class="kicker">FOUR COMPANIONS · TWELVE POSES</div><h1>招呼一声，客人就来。</h1><div class="tabs" id="tabs" role="group" aria-label="选择伙伴"></div></div><p class="intro">参考游戏原画，用可编辑的曲线重绘四位伙伴。<br>保留识别点，让表情与姿态各有性格。</p></section><section class="workspace"><div id="stage" class="stage motion"><span class="stage-label">YAOGUAI KEZHAN / VECTOR STUDY</span><div id="drawing"></div><div class="stage-note"><span>原画识别点保留</span><span>640 × 640 / SVG</span></div></div><div class="details"><div id="reading" class="reading"></div><div id="name" class="name"></div><p class="job" id="job"></p><div id="anchor" class="anchor"></div><div class="label">动作 / 表情</div><div class="poses" id="poses"></div><div class="tools"><button class="tool" id="motion">暂停动作</button><button class="tool" id="line">查看线稿</button><div class="swatches"><button class="swatch active" data-bg="#f3ead8" style="background:#f3ead8" aria-label="纸色"></button><button class="swatch" data-bg="#24382f" style="background:#24382f" aria-label="墨绿"></button><button class="swatch" data-bg="#c64c35" style="background:#c64c35" aria-label="朱红"></button></div></div><div class="ref-row"><div class="ref-box"><img id="reference" alt="游戏角色原画"></div><div class="ref-text"><b>原画参考</b><div id="note"></div></div></div><button class="download" id="download">下载当前 SVG</button></div></section><div class="gallery-top"><h2>十二种姿态</h2><p>点击任一姿态，在上方查看与切换。</p></div><section class="gallery" id="gallery"></section><footer class="footer"><span>此处为宣传用矢量重绘与动作设计，游戏内职能以角色资料为准。<br>原画参考取自 Moshenluo / Yaoguai-Kezhan；SVG 无位图嵌入，可单独编辑分组。</span><span>HTML 已内嵌全部预览资源，可离线使用。<br>轻微动作会遵循设备的减少动态设置。</span></footer></main><script>const DATA=DATAJSON;
let current=0,pose=0;const $=id=>document.getElementById(id);const prefix=(svg,p)=>svg.replace(/id="([^"]+)"/g,(_,id)=>`id="${p}${id}"`).replace(/url\(#([^)]+)\)/g,(_,id)=>`url(#${p}${id})`).replace(/(href|xlink:href)="#([^"]+)"/g,(_,key,id)=>`${key}="#${p}${id}"`).replace(/aria-labelledby="([^"]+)"/g,(_,ids)=>`aria-labelledby="${ids.split(/\s+/).map(id=>p+id).join(' ')}"`);
function select(c,p,scroll=false){current=c;pose=p;const ch=DATA[c];$('name').textContent=ch.name;$('reading').textContent=ch.reading;$('job').textContent=ch.role;$('anchor').textContent=ch.anchor;$('note').textContent=ch.note;$('reference').src=ch.reference;$('reference').alt=ch.name+'原画';$('drawing').innerHTML=prefix(ch.svgs[p],'main-');$('drawing').querySelectorAll('.head,.tail,.ear').forEach(g=>{const w=document.createElementNS('http://www.w3.org/2000/svg','g');w.setAttribute('class','motion-'+(g.classList.contains('head')?'head':g.classList.contains('tail')?'tail':'ear'));g.parentNode.insertBefore(w,g);w.append(g)});$('tabs').querySelectorAll('button').forEach((b,i)=>{b.classList.toggle('active',i===c);b.setAttribute('aria-pressed',String(i===c))});$('poses').innerHTML='';ch.poses.forEach((label,i)=>{const b=document.createElement('button');b.className='pose'+(i===p?' active':'');b.textContent=label;b.setAttribute('aria-pressed',String(i===p));b.onclick=()=>select(current,i);$('poses').append(b)});if(scroll)$('stage').scrollIntoView({behavior:'smooth',block:'start'})}
DATA.forEach((ch,c)=>{const b=document.createElement('button');b.className='tab';b.textContent=ch.name;b.onclick=()=>select(c,0);$('tabs').append(b);ch.svgs.forEach((svg,p)=>{const card=document.createElement('button');card.className='card';card.setAttribute('aria-label',ch.name+' '+ch.poses[p]);card.innerHTML=prefix(svg,`card-${c}-${p}-`)+`<div class="cap"><span>${ch.name}</span><small>${ch.poses[p]}</small></div>`;card.onclick=()=>select(c,p,true);$('gallery').append(card)})});
$('motion').onclick=()=>{const on=$('stage').classList.toggle('motion');$('motion').textContent=on?'暂停动作':'播放动作';$('motion').setAttribute('aria-pressed',String(on))};$('line').onclick=()=>{const on=$('stage').classList.toggle('line-mode');$('line').textContent=on?'查看彩色':'查看线稿';$('line').setAttribute('aria-pressed',String(on))};document.querySelectorAll('[data-bg]').forEach(b=>b.onclick=()=>{$('stage').style.background=b.dataset.bg;document.querySelectorAll('[data-bg]').forEach(x=>x.classList.toggle('active',x===b))});$('download').onclick=()=>{const ch=DATA[current],url=URL.createObjectURL(new Blob([ch.svgs[pose]],{type:'image/svg+xml;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=ch.files[pose].split('/').pop();a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};if(matchMedia('(prefers-reduced-motion: reduce)').matches){$('stage').classList.remove('motion');$('motion').textContent='播放动作'}select(0,0);window.previewReady=document.fonts.ready;window.STUDY={select,DATA};
</script></body></html>'''.replace('STYLE',CSS).replace('DATAJSON',DATA)
(ROOT/'preview-standalone.html').write_text(HTML,encoding='utf-8')
# Static art board for review/export; original artwork is always explicitly labelled.
rows=[]
for i,ch in enumerate(CHARS):
 cells=f'<div class="original"><img src="{ch["reference"]}"><div class="cell-cap">游戏原画</div></div>'
 for n,svg in enumerate(ch['svgs']):
  # Each SVG has its own unique character+pose prefix; original IDs are already isolated per file.
  cells+=f'<div class="vector">{svg}<div class="cell-cap">{ch["poses"][n]}</div></div>'
 rows.append(f'<section class="row"><div class="row-title"><b>{ch["name"]}</b><span>{ch["role"]}</span><small>{ch["anchor"]}</small></div><div class="cells">{cells}</div></section>')
poster=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><style>@font-face{{font-family:song;src:url({fonturi})}}*{{box-sizing:border-box}}body{{width:1600px;margin:0;padding:55px 65px 42px;background:#f3ead8;color:#24382f;font-family:song,serif}}header{{border-bottom:2px solid #c7b794;padding-bottom:28px;display:flex;justify-content:space-between;align-items:end}}header small{{letter-spacing:4px;color:#9a8054;font:14px Arial}}h1{{font-size:55px;letter-spacing:6px;font-weight:500;margin:15px 0 0}}header p{{font-size:19px;line-height:1.8;margin:0;color:#8b7657}}.row{{padding:20px 0 16px;border-bottom:1px solid #d0bd9d}}.row-title{{display:flex;align-items:baseline;gap:21px}}.row-title b{{font-size:29px;font-weight:500;letter-spacing:5px}}.row-title span{{font-size:16px;color:#c64c35}}.row-title small{{margin-left:auto;color:#897a60;font-size:15px}}.cells{{display:grid;grid-template-columns:280px repeat(3,1fr);gap:24px;align-items:center;margin-top:6px}}.original,.vector{{height:330px;position:relative;text-align:center}}.original{{border-right:1px solid #d0bd9d}}.original img{{width:250px;height:289px;object-fit:contain}}.vector svg{{width:302px;height:302px}}.cell-cap{{font-size:16px;letter-spacing:2px;color:#736a55;position:absolute;bottom:0;left:0;right:0}}footer{{display:flex;justify-content:space-between;margin-top:25px;color:#8b7b60;font-size:14px;line-height:1.8}}</style><body><header><div><small>YAOGUAI KEZHAN / CHARACTER STUDY 01</small><h1>山海伙伴 · SVG 角色试绘</h1></div><p>四位伙伴 / 十二种姿态<br>原画识别点保留 · 可编辑分组</p></header>{''.join(rows)}<footer><span>左列为游戏原画；右侧为参考原画重绘的矢量角色与动作设计。</span><span>妖怪客栈 / 2026</span></footer></body></html>'''
(ROOT/'poster.html').write_text(poster,encoding='utf-8')
manifest={'source_commit':'79908426b6586f6fd9a86da571e02884c6f837d4','characters':[{k:v for k,v in ch.items() if k not in ['svgs','reference']} for ch in CHARS]}
(ROOT/'characters.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'characters':len(CHARS),'poses':sum(len(c['svgs']) for c in CHARS),'preview_bytes':len(HTML.encode())},ensure_ascii=False))
